zoe_docs: and the JS retry helper I included (uses AbortSignal to allow cancellable retries):

```js
// JS SDK: cancellable retry on RateLimit
import Redwood from '@redwood/inference'
const client = new Redwood({ apiKey: process.env.TOKEN })

async function generateWithAbort(prompt, signal, retries = 4) {
  let backoff = 500
  for (let i = 0; i < retries; i++) {
    if (signal.aborted) throw new Error('aborted')
    try {
      return await client.generate({ prompt })
    } catch (err) {
      if (err.name === 'RateLimitError') {
        await new Promise(r => setTimeout(r, backoff))
        backoff *= 2
        continue
      }
      throw err
    }
  }
  throw new Error('retries exhausted')
}
```

